import matter from 'gray-matter';
import { marked } from 'marked';

export interface PageFrontmatter {
  title: string;
  date?: string;
  tags?: string[];
  [key: string]: any;
}

export interface ParsedPage {
  frontmatter: PageFrontmatter;
  html: string;
  slug: string;
}

export async function parseMarkdown(content: string, slug: string): Promise<ParsedPage> {
  const { data, content: markdown } = matter(content);

  const frontmatter: PageFrontmatter = {
    title: data.title || 'Untitled',
    date: data.date,
    tags: data.tags || [],
    ...data,
  };

  const html = await marked(markdown);

  return {
    frontmatter,
    html,
    slug,
  };
}

import { ParsedPage, PageFrontmatter } from './parser';

export function generatePageHTML(page: ParsedPage): string {
  const { frontmatter, html, slug } = page;
  const date = frontmatter.date ? new Date(frontmatter.date).toLocaleDateString() : '';
  const tagsList = Array.isArray(frontmatter.tags) ? frontmatter.tags.join(', ') : '';

  return `<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>${escapeHtml(frontmatter.title)}</title>
  <style>
    body {
      font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen, Ubuntu, Cantarell, sans-serif;
      line-height: 1.6;
      max-width: 800px;
      margin: 0 auto;
      padding: 2rem;
      color: #333;
    }
    h1 { font-size: 2.5rem; margin-bottom: 0.5rem; }
    .meta { color: #666; font-size: 0.95rem; margin-bottom: 2rem; }
    .tag { display: inline-block; background: #e0e0e0; padding: 0.25rem 0.75rem; border-radius: 1rem; margin-right: 0.5rem; font-size: 0.9rem; }
    a { color: #0066cc; text-decoration: none; }
    a:hover { text-decoration: underline; }
    .nav { margin-bottom: 2rem; }
    .nav a { margin-right: 1rem; }
  </style>
</head>
<body>
  <div class="nav">
    <a href="index.html">← Back to index</a>
  </div>
  <article>
    <h1>${escapeHtml(frontmatter.title)}</h1>
    <div class="meta">
      ${date ? `<div>Published: ${date}</div>` : ''}
      ${tagsList ? `<div class="tags">${frontmatter.tags!.map((tag: string) => `<span class="tag">${escapeHtml(tag)}</span>`).join('')}</div>` : ''}
    </div>
    <div class="content">
      ${html}
    </div>
  </article>
</body>
</html>`;
}

export function generateIndexHTML(pages: ParsedPage[]): string {
  const sortedPages = pages.sort((a, b) => {
    const dateA = a.frontmatter.date ? new Date(a.frontmatter.date).getTime() : 0;
    const dateB = b.frontmatter.date ? new Date(b.frontmatter.date).getTime() : 0;
    return dateB - dateA;
  });

  const pageList = sortedPages
    .map(page => {
      const date = page.frontmatter.date ? new Date(page.frontmatter.date).toLocaleDateString() : 'No date';
      return `<li>
  <a href="${escapeHtml(page.slug)}.html">${escapeHtml(page.frontmatter.title)}</a>
  <span class="date">${date}</span>
</li>`;
    })
    .join('\n');

  return `<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Site Index</title>
  <style>
    body {
      font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen, Ubuntu, Cantarell, sans-serif;
      line-height: 1.6;
      max-width: 800px;
      margin: 0 auto;
      padding: 2rem;
      color: #333;
    }
    h1 { font-size: 2.5rem; margin-bottom: 2rem; }
    ul { list-style: none; padding: 0; }
    li {
      padding: 1rem 0;
      border-bottom: 1px solid #e0e0e0;
      display: flex;
      justify-content: space-between;
      align-items: center;
    }
    a { color: #0066cc; text-decoration: none; }
    a:hover { text-decoration: underline; }
    .date { color: #999; font-size: 0.9rem; }
  </style>
</head>
<body>
  <h1>Site Index</h1>
  <p>${pages.length} page${pages.length !== 1 ? 's' : ''} found</p>
  <ul>
${pageList}
  </ul>
</body>
</html>`;
}

function escapeHtml(text: string): string {
  const map: { [key: string]: string } = {
    '&': '&amp;',
    '<': '&lt;',
    '>': '&gt;',
    '"': '&quot;',
    "'": '&#039;',
  };
  return text.replace(/[&<>"']/g, char => map[char]);
}

#!/usr/bin/env node

import fs from 'fs';
import path from 'path';
import { parseMarkdown } from './parser';
import { generatePageHTML, generateIndexHTML } from './generator';

interface CliOptions {
  content: string;
  output: string;
}

function parseArgs(): CliOptions {
  const args = process.argv.slice(2);
  const options: CliOptions = {
    content: './content',
    output: './dist',
  };

  for (let i = 0; i < args.length; i++) {
    if (args[i] === '--content' && args[i + 1]) {
      options.content = args[i + 1];
      i++;
    } else if (args[i] === '--output' && args[i + 1]) {
      options.output = args[i + 1];
      i++;
    }
  }

  return options;
}

async function build(options: CliOptions): Promise<void> {
  const { content: contentDir, output: outputDir } = options;

  if (!fs.existsSync(contentDir)) {
    console.error(`Error: Content directory "${contentDir}" does not exist`);
    process.exit(1);
  }

  if (!fs.existsSync(outputDir)) {
    fs.mkdirSync(outputDir, { recursive: true });
  }

  const files = fs.readdirSync(contentDir).filter(file => file.endsWith('.md'));

  if (files.length === 0) {
    console.warn(`Warning: No markdown files found in "${contentDir}"`);
  }

  const pages = [];

  for (const file of files) {
    const filePath = path.join(contentDir, file);
    const content = fs.readFileSync(filePath, 'utf-8');
    const slug = path.parse(file).name;

    try {
      const page = await parseMarkdown(content, slug);
      pages.push(page);

      const outputFile = path.join(outputDir, `${slug}.html`);
      const html = generatePageHTML(page);
      fs.writeFileSync(outputFile, html, 'utf-8');
      console.log(`✓ Generated ${outputFile}`);
    } catch (error) {
      console.error(`Error processing ${file}:`, error);
      process.exit(1);
    }
  }

  const indexFile = path.join(outputDir, 'index.html');
  const indexHtml = generateIndexHTML(pages);
  fs.writeFileSync(indexFile, indexHtml, 'utf-8');
  console.log(`✓ Generated ${indexFile}`);

  console.log(`\nBuild complete: ${pages.length} page${pages.length !== 1 ? 's' : ''} generated`);
}

const command = process.argv[2];

if (command === 'build' || !command) {
  const options = parseArgs();
  build(options).catch(error => {
    console.error('Build failed:', error);
    process.exit(1);
  });
} else {
  console.error(`Unknown command: ${command}`);
  console.error('Usage: ssg build [--content <dir>] [--output <dir>]');
  process.exit(1);
}

import { parseMarkdown } from '../parser';

describe('parser', () => {
  describe('parseMarkdown', () => {
    it('should parse simple markdown without frontmatter', async () => {
      const content = '# Hello World\n\nThis is a test.';
      const result = await parseMarkdown(content, 'test');

      expect(result.slug).toBe('test');
      expect(result.frontmatter.title).toBe('Untitled');
      expect(result.html).toContain('<h1>Hello World</h1>');
      expect(result.html).toContain('<p>This is a test.</p>');
    });

    it('should parse markdown with frontmatter', async () => {
      const content = `---
title: My Post
date: 2024-01-15
tags:
  - typescript
  - testing
---

# Content

This is the body.`;
      const result = await parseMarkdown(content, 'my-post');

      expect(result.slug).toBe('my-post');
      expect(result.frontmatter.title).toBe('My Post');
      expect(result.frontmatter.date).toBe('2024-01-15');
      expect(result.frontmatter.tags).toEqual(['typescript', 'testing']);
      expect(result.html).toContain('<h1>Content</h1>');
      expect(result.html).toContain('<p>This is the body.</p>');
    });

    it('should handle markdown with headings and lists', async () => {
      const content = `---
title: Test Post
---

## Section

- Item 1
- Item 2
- Item 3`;
      const result = await parseMarkdown(content, 'test-post');

      expect(result.frontmatter.title).toBe('Test Post');
      expect(result.html).toContain('<h2>Section</h2>');
      expect(result.html).toContain('<li>Item 1</li>');
      expect(result.html).toContain('<li>Item 2</li>');
      expect(result.html).toContain('<li>Item 3</li>');
    });

    it('should handle markdown with code blocks', async () => {
      const content = `---
title: Code Example
---

\`\`\`typescript
const x = 42;
\`\`\``;
      const result = await parseMarkdown(content, 'code');

      expect(result.frontmatter.title).toBe('Code Example');
      expect(result.html).toContain('<code>');
      expect(result.html).toContain('const x = 42;');
    });

    it('should preserve custom frontmatter properties', async () => {
      const content = `---
title: Test
author: John Doe
category: tech
---

Content`;
      const result = await parseMarkdown(content, 'test');

      expect(result.frontmatter.author).toBe('John Doe');
      expect(result.frontmatter.category).toBe('tech');
    });

    it('should handle empty tags', async () => {
      const content = `---
title: Test
---

Content`;
      const result = await parseMarkdown(content, 'test');

      expect(result.frontmatter.tags).toEqual([]);
    });
  });
});

import { generatePageHTML, generateIndexHTML } from '../generator';
import { ParsedPage } from '../parser';

describe('generator', () => {
  describe('generatePageHTML', () => {
    it('should generate valid HTML for a page', () => {
      const page: ParsedPage = {
        slug: 'test-page',
        frontmatter: {
          title: 'Test Page',
          date: '2024-01-15',
          tags: ['test', 'example'],
        },
        html: '<p>This is test content</p>',
      };

      const result = generatePageHTML(page);

      expect(result).toContain('<!DOCTYPE html>');
      expect(result).toContain('<title>Test Page</title>');
      expect(result).toContain('<h1>Test Page</h1>');
      expect(result).toContain('Published: 1/15/2024');
      expect(result).toContain('<span class="tag">test</span>');
      expect(result).toContain('<span class="tag">example</span>');
      expect(result).toContain('<p>This is test content</p>');
      expect(result).toContain('<a href="index.html">← Back to index</a>');
    });

    it('should handle pages without date', () => {
      const page: ParsedPage = {
        slug: 'no-date',
        frontmatter: {
          title: 'No Date Post',
        },
        html: '<p>Content</p>',
      };

      const result = generatePageHTML(page);

      expect(result).toContain('<title>No Date Post</title>');
      expect(result).not.toContain('Published:');
      expect(result).toContain('<p>Content</p>');
    });

    it('should handle pages without tags', () => {
      const page: ParsedPage = {
        slug: 'no-tags',
        frontmatter: {
          title: 'No Tags',
          tags: [],
        },
        html: '<p>Content</p>',
      };

      const result = generatePageHTML(page);

      expect(result).not.toContain('class="tag"');
    });

    it('should escape HTML in title', () => {
      const page: ParsedPage = {
        slug: 'xss-test',
        frontmatter: {
          title: '<script>alert("xss")</script>',
        },
        html: '<p>Content</p>',
      };

      const result = generatePageHTML(page);

      expect(result).not.toContain('<script>');
      expect(result).toContain('&lt;script&gt;');
    });

    it('should escape HTML in tags', () => {
      const page: ParsedPage = {
        slug: 'tag-escape',
        frontmatter: {
          title: 'Test',
          tags: ['<bad>', '"quote"'],
        },
        html: '<p>Content</p>',
      };

      const result = generatePageHTML(page);

      expect(result).toContain('&lt;bad&gt;');
      expect(result).toContain('&quot;quote&quot;');
    });
  });

  describe('generateIndexHTML', () => {
    it('should generate index with multiple pages', () => {
      const pages: ParsedPage[] = [
        {
          slug: 'first',
          frontmatter: { title: 'First Post', date: '2024-01-15' },
          html: '<p>First</p>',
        },
        {
          slug: 'second',
          frontmatter: { title: 'Second Post', date: '2024-01-10' },
          html: '<p>Second</p>',
        },
      ];

      const result = generateIndexHTML(pages);

      expect(result).toContain('<!DOCTYPE html>');
      expect(result).toContain('<title>Site Index</title>');
      expect(result).toContain('<h1>Site Index</h1>');
      expect(result).toContain('2 pages found');
      expect(result).toContain('<a href="first.html">First Post</a>');
      expect(result).toContain('<a href="second.html">Second Post</a>');
    });

    it('should sort pages by date in descending order', () => {
      const pages: ParsedPage[] = [
        {
          slug: 'old',
          frontmatter: { title: 'Old Post', date: '2024-01-01' },
          html: '<p>Old</p>',
        },
        {
          slug: 'new',
          frontmatter: { title: 'New Post', date: '2024-01-31' },
          html: '<p>New</p>',
        },
      ];

      const result = generateIndexHTML(pages);

      const newIndex = result.indexOf('New Post');
      const oldIndex = result.indexOf('Old Post');
      expect(newIndex).toBeLessThan(oldIndex);
    });

    it('should handle pages without dates', () => {
      const pages: ParsedPage[] = [
        {
          slug: 'with-date',
          frontmatter: { title: 'With Date', date: '2024-01-15' },
          html: '<p>Content</p>',
        },
        {
          slug: 'no-date',
          frontmatter: { title: 'No Date' },
          html: '<p>Content</p>',
        },
      ];

      const result = generateIndexHTML(pages);

      expect(result).toContain('With Date');
      expect(result).toContain('No Date');
      expect(result).toContain('No date');
    });

    it('should display correct page count', () => {
      const pages: ParsedPage[] = [
        {
          slug: 'one',
          frontmatter: { title: 'One' },
          html: '<p>One</p>',
        },
      ];

      const result = generateIndexHTML(pages);
      expect(result).toContain('1 page found');

      const pages2: ParsedPage[] = Array(5)
        .fill(null)
        .map((_, i) => ({
          slug: `page-${i}`,
          frontmatter: { title: `Page ${i}` },
          html: '<p>Content</p>',
        }));

      const result2 = generateIndexHTML(pages2);
      expect(result2).toContain('5 pages found');
    });

    it('should escape HTML in page titles', () => {
      const pages: ParsedPage[] = [
        {
          slug: 'xss',
          frontmatter: { title: '<img src=x onerror=alert(1)>' },
          html: '<p>Content</p>',
        },
      ];

      const result = generateIndexHTML(pages);

      expect(result).not.toContain('<img src=');
      expect(result).toContain('&lt;img');
    });
  });
});

import fs from 'fs';
import path from 'path';
import { execSync } from 'child_process';

describe('CLI integration', () => {
  const testDir = path.join(__dirname, '../..', '.test-ssg');
  const contentDir = path.join(testDir, 'content');
  const outputDir = path.join(testDir, 'dist');

  beforeEach(() => {
    if (fs.existsSync(testDir)) {
      fs.rmSync(testDir, { recursive: true });
    }
    fs.mkdirSync(contentDir, { recursive: true });
  });

  afterEach(() => {
    if (fs.existsSync(testDir)) {
      fs.rmSync(testDir, { recursive: true });
    }
  });

  it('should build the site from markdown files', () => {
    const content = `---
title: Test Post
date: 2024-01-15
tags:
  - test
---

# Content

This is a test post.`;

    fs.writeFileSync(path.join(contentDir, 'test.md'), content);

    execSync(
      `npm run build && node dist/cli.js build --content ${contentDir} --output ${outputDir}`,
      { cwd: path.join(__dirname, '../..'), stdio: 'pipe' }
    );

    expect(fs.existsSync(outputDir)).toBe(true);
    expect(fs.existsSync(path.join(outputDir, 'test.html'))).toBe(true);
    expect(fs.existsSync(path.join(outputDir, 'index.html'))).toBe(true);

    const testHtml = fs.readFileSync(path.join(outputDir, 'test.html'), 'utf-8');
    expect(testHtml).toContain('Test Post');
    expect(testHtml).toContain('<h1>Content</h1>');
    expect(testHtml).toContain('This is a test post');
  });

  it('should generate index.html with all pages', () => {
    const post1 = `---
title: First Post
date: 2024-01-15
---

First content`;

    const post2 = `---
title: Second Post
date: 2024-01-10
---

Second content`;

    fs.writeFileSync(path.join(contentDir, 'first.md'), post1);
    fs.writeFileSync(path.join(contentDir, 'second.md'), post2);

    execSync(
      `npm run build && node dist/cli.js build --content ${contentDir} --output ${outputDir}`,
      { cwd: path.join(__dirname, '../..'), stdio: 'pipe' }
    );

    const indexHtml = fs.readFileSync(path.join(outputDir, 'index.html'), 'utf-8');
    expect(indexHtml).toContain('First Post');
    expect(indexHtml).toContain('Second Post');
    expect(indexHtml).toContain('2 pages found');
  });

  it('should use default directories if not specified', () => {
    const defaultContent = `---
title: Default Post
---

Content`;

    if (!fs.existsSync('./content')) {
      fs.mkdirSync('./content', { recursive: true });
    }
    fs.writeFileSync('./content/default.md', defaultContent);

    try {
      execSync('npm run build && node dist/cli.js build', {
        cwd: path.join(__dirname, '../..'),
        stdio: 'pipe',
      });

      expect(fs.existsSync('./dist/default.html')).toBe(true);
      expect(fs.existsSync('./dist/index.html')).toBe(true);
    } finally {
      if (fs.existsSync('./content')) {
        fs.rmSync('./content', { recursive: true });
      }
      if (fs.existsSync('./dist')) {
        fs.rmSync('./dist', { recursive: true });
      }
    }
  });

  it('should handle custom content and output directories', () => {
    const customContent = `---
title: Custom Dir Post
---

Content`;

    fs.writeFileSync(path.join(contentDir, 'custom.md'), customContent);

    execSync(
      `npm run build && node dist/cli.js build --content "${contentDir}" --output "${outputDir}"`,
      { cwd: path.join(__dirname, '../..'), stdio: 'pipe' }
    );

    expect(fs.existsSync(path.join(outputDir, 'custom.html'))).toBe(true);
  });
});

